'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var dlasyf = require( './../lib' ).ndarray;


// FUNCTIONS //

/**
* Creates a bounded reset-and-factor benchmark.
*
* @private
* @param {PositiveInteger} N - matrix order
* @param {PositiveInteger} NB - panel width
* @param {string} uplo - stored triangle
* @returns {Function} benchmark function
*/
function createBenchmark( N, NB, uplo ) {
	var original;
	var IPIV;
	var KB;
	var A;
	var W;
	var i;
	var j;

	original = new Float64Array( N*N );
	A = new Float64Array( N*N );
	W = new Float64Array( N*NB );
	IPIV = new Int32Array( N );
	KB = new Int32Array( 1 );
	for ( i = 0; i < N; i++ ) {
		for ( j = 0; j < N; j++ ) {
			if ( i === j ) {
				original[ (i*N)+j ] = N + 2.0;
			} else if ( ( uplo === 'upper' && i < j ) || ( uplo === 'lower' && i > j ) ) {
				original[ (i*N)+j ] = 0.25;
			} else {
				original[ (i*N)+j ] = 999.0;
			}
		}
	}
	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var expected;
		var start;
		var info;
		var stop;
		var i;

		expected = ( N <= NB ) ? N : NB-1;
		info = 0;
		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			// Include resetting the changed input in each iteration:
			A.set( original );
			info = dlasyf( uplo, N, NB, KB, 0, A, N, 1, 0, IPIV, 1, 0, W, NB, 1, 0 ); // eslint-disable-line max-len
			if ( info !== 0 || KB[ 0 ] !== expected ) {
				b.fail( 'should factor the expected nonsingular panel' );
				break;
			}
		}
		b.toc();
		start = ( uplo === 'upper' ) ? N-expected : 0;
		stop = start + expected;
		for ( i = start; i < stop; i++ ) {
			if ( IPIV[ i ] !== i+1 ) {
				b.fail( 'should produce the expected identity pivot targets' );
				break;
			}
		}
		if ( ( uplo === 'upper' && A[ N ] !== 999.0 ) || ( uplo === 'lower' && A[ 1 ] !== 999.0 ) ) {
			b.fail( 'should preserve the ignored triangle' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var options;
	var sizes;
	var uplos;
	var width;
	var name;
	var fcn;
	var i;
	var j;
	var k;

	options = {
		'iterations': 200,
		'repeats': 2
	};
	sizes = [ 8, 16 ];
	uplos = [ 'upper', 'lower' ];
	for ( i = 0; i < sizes.length; i++ ) {
		for ( j = 0; j < uplos.length; j++ ) {
			for ( k = 0; k < 2; k++ ) {
				width = ( k === 1 ) ? sizes[ i ] : 4;
				name = format( '%s:ndarray:triangle=%s:N=%d:NB=%d', pkg, uplos[ j ], sizes[ i ], width );
				fcn = createBenchmark( sizes[ i ], width, uplos[ j ] );
				bench( name, options, fcn );
			}
		}
	}
}

main();
